<script type="text/javascript">
//jQuery(document).ready(function() {
Dropzone.autoDiscover = false;
if(jQuery('div#myDrop').length > 0)
{
    Dropzone.options.myAwesomeDropzone = false;
    var myDropzone = new Dropzone("div#myDrop", { 
        url: "<?php echo url_for('com_recibida/dzFileUpload?comrecibida_id='.$com_recibida->getPrimaryKey()); ?>",
        autoProcessQueue: true,
        addRemoveLinks: true,
        thumbnailWidth: 50,
        thumbnailHeight: 50,
        parallelUploads: 100,
        maxFiles: 10,
        timeout: 0,
        maxFilesize: 1024,
        dictResponseError: "Ha ocurrido un error en el server",
        acceptedFiles: 'image/*,.jpeg,.jpg,.png,.gif,.JPEG,.JPG,.PNG,.GIF,.TIF,.TIFF,.tif,.tiff,.zip,.7z,.rar,application/pdf,.psd,.csv,.xls,.doc,.dat,.ppt,.msg,.mso,.xlsx,.docx,.pptx,.txt,.3gp,.m4a,.mp3,.avi,.dwg,.kmz,.kmz,.wmv,.wav,.mp4,.m4v,.mov,.mpg,.mpeg,.mpeg-4,.avc,.acc_lc,.acc,.mpc-hc,.mpc,.mid,.midi,.gdb,.asf,.aac,.ogg,.opus,.wmz',
        init: function () {
            this.on("success", function (file, response) {
                jQuery(file.previewElement).find('[data-dz-name]').html(response.name);
                var active_value = jQuery('#archivo').val().trim() != "" ? jQuery('#archivo').val() + "," + response.name : response.name;
                jQuery('#archivo').val(active_value);
            });
            
            this.on("removedfile", function(file) {
                if(file != null)
                {
                    var active_new = [];
                    var active_files = jQuery('#archivo').val().split(",");
                    var index = 0;
                    for(i=0; i < active_files.length; i++){
                        if(file.name != active_files[i]){
                            active_new.push(active_files[i]);
                        }
                        index++;
                    }
                    jQuery('#archivo').val(active_new.join(","));
                }
            });
        }
    });    
    //Add existing files into dropzone
    var existingFiles = <?php echo $json_files ? $json_files : null; ?>;
    for (i = 0; i < existingFiles.length; i++) {
        myDropzone.emit("addedfile", existingFiles[i]);
        myDropzone.emit("complete", existingFiles[i]);                
    }
}
//});
</script>